import 'dart:convert';
import 'package:http/http.dart' as http;

class Name {
  final String common;
  final String official;

  Name({required this.common, required this.official});

  factory Name.fromJson(Map<String, dynamic> json) {
    return Name(
      common: json['common'] ?? '',
      official: json['official'] ?? '',
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'common': common,
      'official': official,
      'nativeName': nativeName.map((key, value) => MapEntry(key, value.toJson())),
    };
  }
}

class Currency {
  final String name;
  final String symbol;

  Currency({required this.name, required this.symbol});

  factory Currency.fromJson(Map<String, dynamic> json) {
    return Currency(
      name: json['name'] ?? '',
      symbol: json['symbol'] ?? '',
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'name': name,
      'symbol': symbol,
    };
  }
}

class Language {
  final String code;
  final String name;

  Language({required this.code, required this.name});

  factory Language.fromJson(MapEntry<String, dynamic> entry) {
    return Language(
      code: entry.key, 
      name: entry.value.toString()
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'code': code,
      'name': name,
    };
  }
}

class Country {
  final Name name;
  final String region;
  final String capital;
  final Map<String, Currency> currencies;
  final Map<String, String> languages;

  Country({
    required this.name,
    required this.region,
    required this.capital,
    required this.currencies,
    required this.languages,
  });

  factory Country.fromJson(Map<String, dynamic> json) {
    final currenciesJson = (json['currencies'] ?? {}) as Map<String, dynamic>;
    final languagesJson = (json['languages'] ?? {}) as Map<String, dynamic>;

    return Country(
      name: Name.fromJson(json['name']),
      region: json['region'] ?? '',
      capital: (json['capital'] is List && json['capital'].isNotEmpty)
          ? json['capital'][0]
          : (json['capital'] ?? ''),
      currencies: currenciesJson.map(
        (k, v) => MapEntry(k, Currency.fromJson(v)),
      ),
      languages: languagesJson.map((k, v) => MapEntry(k, v.toString())),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'name': name.toJson(),
      'region': region,
      'capital': capital,
      'currencies': currencies.map((k, v) => MapEntry(k, v.toJson())),
      'languages': languages,
    };
  }

  // MÉTODO ESTÁTICO - Muy lógico porque está relacionado con Country
  static Future<Country?> fetchByName(String name) async {
    try {
      final response = await http.get(
        Uri.parse('https://restcountries.com/v2/name/$name')
      );

      if (response.statusCode == 200) {
        final List data = jsonDecode(response.body);
        return Country.fromJson(data.first);
      } else if (response.statusCode == 404) {
        print('❌ País no encontrado: $name');
        return null;
      } else {
        throw Exception('Error del servidor: ${response.statusCode}');
      }
    } on http.ClientException catch (e) {
      print('⚠ Error de red: $e');
      return null;
    } on FormatException catch (e) {
      print('⚠ Error de formato JSON: $e');
      return null;
    } catch (e) {
      print('⚠ Error inesperado: $e');
      return null;
    }
  }

  // Podrías añadir más métodos estáticos útiles
  static Future<List<Country>> fetchByRegion(String region) async {
    // Implementación para buscar por región
    // ...
    return [];
  }

  static Future<List<Country>> fetchAll() async {
    // Implementación para obtener todos los países
    // ...
    return [];
  }
}

void ejercicio3() async {
  final country = await Country.fetchByName('peru');
  if (country != null) {
    print('País: ${country.name.common}');
    print('Capital: ${country.capital}');
    print('Moneda: ${country.currencies.values.first.name}');
    print('Símbolo: ${country.currencies.values.first.symbol}');
    print('Idioma principal: ${country.languages.values.first}');
  }
}
